    "citser": "https://stics.linkeddata.es/def/citser#"
  },
  "@id": "{{assetId}}",
  "@type": "Asset",
  "properties": {
    "name": "Toolbox HttpData asset",
    "version": "1.0.0",
    "contenttype": "application/json",
    "assetType": "dataset",
    "shortDescription": "Asset created from the STICS Postman toolbox",
    "dcterms:description": "Asset created from the STICS Postman toolbox",
    "dcat:keyword": [
      "toolbox",
      "test"
    ]
  },
  "dataAddress": {
    "type": "HttpData",
    "name": "{{assetId}}",
    "baseUrl": "{{httpBaseUrl}}",
    "proxyPath": "true"
  }
}

